#!/usr/bin/env bash
# Copies the exported brand icon and splash symbol into the iOS asset catalog.
# Source files are generated by brand/logo/src/variants.py and must never be edited by hand
# (see brand/LOGO.md); this script only copies them as-is, so re-running it is a no-op (no git diff).
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ios_app_dir="$(cd "${script_dir}/.." && pwd)"
repo_root="$(cd "${ios_app_dir}/../.." && pwd)"

brand_app_icon_dir="${repo_root}/brand/logo/app-icon"
brand_color_dir="${repo_root}/brand/logo/color"
assets_dir="${ios_app_dir}/iosApp/Assets.xcassets"

app_icon_set="${assets_dir}/AppIcon.appiconset"
launch_symbol_set="${assets_dir}/LaunchSymbol.imageset"

cp "${brand_app_icon_dir}/ios-light-1024.png" "${app_icon_set}/ios-light-1024.png"
cp "${brand_app_icon_dir}/ios-dark-1024.png" "${app_icon_set}/ios-dark-1024.png"
cp "${brand_app_icon_dir}/ios-tinted-1024.png" "${app_icon_set}/ios-tinted-1024.png"

cp "${brand_color_dir}/symbol-deep.svg" "${launch_symbol_set}/symbol-deep.svg"
cp "${brand_color_dir}/symbol-cyan.svg" "${launch_symbol_set}/symbol-cyan.svg"

echo "Synced brand assets into ${assets_dir#"${repo_root}"/}"
